style.css:
body {
  background-color: var(--background-color, #2e3440) !important;
  font-family: 'Arial', sans-serif; /* Default font for body */
}

/* General styles for strong and em */
strong {
  color: var(--strong-color, #ebcb8b) !important;
  font-family: 'Courier New', monospace; /* Font for strong */
}

em {
  color: var(--em-color, #88c0d0) !important;
  font-family: 'Georgia', serif; /* Font for em */
}

/* Specific styles for headings */
h1 strong, h1 em,
h2 strong, h2 em,
h3 strong, h3 em,
h4 strong, h4 em,
h5 strong, h5 em,
h6 strong, h6 em {
  color: inherit !important; /* or set to a specific color for headings */
}

/* Specific colors and fonts for headings */
h1 {
  color: var(--h1-color, #bf616a) !important;
  font-family: 'Helvetica', sans-serif; /* Font for h1 */
}

h2 {
  color: var(--h2-color, #a3be8c) !important;
  font-family: 'Tahoma', sans-serif; /* Font for h2 */
}

h3 {
  color: var(--h3-color, #b48ead) !important;
  font-family: 'Verdana', sans-serif; /* Font for h3 */
}

h4 {
  color: var(--h4-color, #b48ead) !important;
  font-family: 'Times New Roman', serif; /* Font for h4 */
}

h5 {
  color: var(--h5-color, #8fbcbb) !important;
  font-family: 'Arial', sans-serif; /* Font for h5 */
}

h6 {
  color: var(--h6-color, #ebcb8b) !important;
  font-family: 'Impact', sans-serif; /* Font for h6 */
}
